/* Chelsea DNA — royal blue night at the Bridge, lion gold */
.theme-chelsea {
  --bg: oklch(0.258 0.088 259.8);
  --surface: oklch(0.302 0.107 261.3);
  --surface-2: oklch(0.347 0.120 261.6);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.728 0.059 261.7);
  --accent: oklch(0.744 0.150 82.0);
  --accent-fg: oklch(0.258 0.088 259.8);
  --accent-2: oklch(0.489 0.140 251.9);
  --line: oklch(1 0 0 / 15%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.744 0.150 82.0);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Kanit", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-chelsea h1,
.theme-chelsea h2,
.theme-chelsea h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-chelsea { --font-ui: var(--font-display); }
.theme-chelsea h1, .theme-chelsea h2 { text-transform: uppercase; }
.theme-chelsea button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-chelsea { background-image: radial-gradient(ellipse at 50% -10%, oklch(0.5 0.13 255 / 40%), transparent 55%); }
.theme-chelsea h1 { font-weight: 700; }
.theme-chelsea h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent); }

/* depth */
.theme-chelsea thead th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid var(--accent); }
.theme-chelsea td { border-bottom: 1px solid var(--line); }
.theme-chelsea tbody tr:hover { background: oklch(0.36 0.12 261); }
.theme-chelsea a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: oklch(0.744 0.150 82.0 / 50%); }
.theme-chelsea a:hover { text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
.theme-chelsea ::selection { background: oklch(0.744 0.150 82.0); color: oklch(0.22 0.08 260); }
.theme-chelsea input, .theme-chelsea select, .theme-chelsea textarea { background: oklch(0.23 0.08 260); border-color: var(--line); }
.theme-chelsea input:focus-visible, .theme-chelsea select:focus-visible, .theme-chelsea textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-chelsea kbd { background: oklch(0.23 0.08 260); border: 1px solid var(--line); border-bottom: 3px solid var(--accent); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-chelsea ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-chelsea ::-webkit-scrollbar-track { background: oklch(0.22 0.08 260); }
.theme-chelsea ::-webkit-scrollbar-thumb { background: oklch(0.60 0.13 82); border-radius: 5px; border: 2px solid oklch(0.22 0.08 260); }
.theme-chelsea ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-chelsea .label-caps { color: var(--accent); }
/* lion-gold braid along framed panels, pressed shirt-button feel */
.theme-chelsea .themed-border { border-top: 3px solid var(--accent); }
.theme-chelsea button:active { transform: translateY(1px); box-shadow: none; }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-chelsea.alt-mode {
  --bg: oklch(0.159 0 0);
  --surface: oklch(0.200 0 0);
  --surface-2: oklch(0.248 0 0);
  --fg: oklch(0.943 0.026 92.4);
  --fg-muted: oklch(0.661 0.033 90.4);
  --accent: oklch(0.735 0.146 84.3);
  --accent-fg: oklch(0.159 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(0.75 0.1 85 / 30%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-chelsea.alt-mode h1 { color: #d4a017; }
.theme-chelsea.alt-mode h1::after { background: #d4a017; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
